from sklearn.dummy import DummyClassifier
from sklearn.model_selection import StratifiedKFold
from sklearn.metrics import (
    accuracy_score,
    f1_score,
    precision_score,
    recall_score,
    confusion_matrix
)

# ------------------------------------------
# 5-fold stratified cross-validation
# ------------------------------------------
cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)

# store fold-level metrics for downstream stats / ANOVA
fold_results_dummy = []

# to accumulate predictions across all folds for one overall confusion matrix
all_y_true = []
all_y_pred = []

for fold, (train_idx, test_idx) in enumerate(cv.split(X, y), start=1):
    X_train_fold = X.iloc[train_idx]
    X_test_fold = X.iloc[test_idx]
    y_train_fold = y.iloc[train_idx]
    y_test_fold = y.iloc[test_idx]

    # model
    dummy = DummyClassifier(strategy="most_frequent")
    dummy.fit(X_train_fold, y_train_fold)
    y_pred_fold = dummy.predict(X_test_fold)

    # metrics for this fold
    acc = accuracy_score(y_test_fold, y_pred_fold)
    macro_f1 = f1_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)
    macro_precision = precision_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)
    macro_recall = recall_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)

    fold_results_dummy.append({
        "model": "DummyClassifier_most_frequent",
        "fold": fold,
        "accuracy": acc,
        "macro_f1": macro_f1,
        "macro_precision": macro_precision,
        "macro_recall": macro_recall
    })

    all_y_true.extend(y_test_fold)
    all_y_pred.extend(y_pred_fold)

    print(f"\nFold {fold}")
    print(f"Accuracy: {acc:.4f}")
    print(f"Macro F1: {macro_f1:.4f}")
    print(f"Macro Precision: {macro_precision:.4f}")
    print(f"Macro Recall: {macro_recall:.4f}")

# ------------------------------------------
# convert fold metrics to dataframe
# ------------------------------------------
results_df = pd.DataFrame(fold_results_dummy)

print("\n=== Fold-level results ===")
