import tensorflow as tf
# ------------------------------------------
# Optional but recommended for reproducibility
# ------------------------------------------
np.random.seed(40)
tf.random.set_seed(40)

le = LabelEncoder()
y_f = pd.Series(le.fit_transform(y_f), index=y_f.index)
# ------------------------------------------
# helper function to build the MLP
# ------------------------------------------
def build_mlp(input_dim, num_classes):
    model = keras.Sequential([
        layers.Input(shape=(input_dim,)),

        layers.Dense(256, activation='relu'),
        layers.BatchNormalization(),
        layers.Dropout(0.3),

        layers.Dense(128, activation='relu'),
        layers.BatchNormalization(),
        layers.Dropout(0.3),

        layers.Dense(num_classes, activation='softmax')
    ])

    model.compile(
        optimizer='adam',
        loss='sparse_categorical_crossentropy',
        metrics=['accuracy']
    )

    return model

# ------------------------------------------
# 5-fold stratified cross-validation
# ------------------------------------------
cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)

# store fold-level metrics
fold_results_mlp = []

# to accumulate predictions across all folds for one overall confusion matrix
all_y_true_mlp = []
all_y_pred_mlp = []

# if X_f is a pandas DataFrame and y_f is a pandas Series, this works directly
input_dim = X_f.shape[1]
num_classes = len(np.unique(y_f))

for fold, (train_idx, test_idx) in enumerate(cv.split(X_f, y_f), start=1):
    # split data
    X_train_fold = X_f.iloc[train_idx]
    X_test_fold = X_f.iloc[test_idx]
    y_train_fold = y_f.iloc[train_idx]
    y_test_fold = y_f.iloc[test_idx]

    # convert to numpy arrays for keras
    X_train_fold = X_train_fold.to_numpy().astype("float32")
    X_test_fold = X_test_fold.to_numpy().astype("float32")
    y_train_fold = y_train_fold.to_numpy()
    y_test_fold = y_test_fold.to_numpy()

    # clear previous keras graph/session
    keras.backend.clear_session()

    # build fresh model for this fold
    model = build_mlp(input_dim=input_dim, num_classes=num_classes)

    # early stopping
    early_stopping = keras.callbacks.EarlyStopping(
        monitor='val_loss',
        patience=10,
        restore_best_weights=True
    )

    # train model
    history = model.fit(
        X_train_fold, y_train_fold,
        validation_split=0.2,
        epochs=100,
        batch_size=256,
        callbacks=[early_stopping],
        verbose=0
    )

    # predict
    y_pred_proba_fold = model.predict(X_test_fold, verbose=0)
    y_pred_fold = np.argmax(y_pred_proba_fold, axis=1)

    # metrics for this fold
    acc = accuracy_score(y_test_fold, y_pred_fold)
    macro_f1 = f1_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)
    macro_precision = precision_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)
    macro_recall = recall_score(y_test_fold, y_pred_fold, average="macro", zero_division=0)

    fold_results_mlp.append({
        "model": "MLP",
        "fold": fold,
        "accuracy": acc,
        "macro_f1": macro_f1,
        "macro_precision": macro_precision,
        "macro_recall": macro_recall
    })

    all_y_true_mlp.extend(y_test_fold)
    all_y_pred_mlp.extend(y_pred_fold)

    print(f"\nFold {fold}")
    print(f"Accuracy: {acc:.4f}")
    print(f"Macro F1: {macro_f1:.4f}")
    print(f"Macro Precision: {macro_precision:.4f}")
    print(f"Macro Recall: {macro_recall:.4f}")

# ------------------------------------------
# convert fold metrics to dataframe
# ------------------------------------------
