import os
import glob
import numpy as np
import pandas as pd
from scipy import stats
from statsmodels.stats.multicomp import pairwise_tukeyhsd
import statsmodels.api as sm
from statsmodels.formula.api import ols
from statsmodels.stats.libqsturng import qsturng

# --------------------------------------------------
# 1. Load and combine all CV result CSVs
# --------------------------------------------------

csv_files = glob.glob("*_cv_fold_results.csv")

dfs = []
for file in csv_files:
    df = pd.read_csv(file)

    # If you want cleaner model names from filenames:
    # bernnb_cv_fold_results.csv -> BernoulliNB
    # dummy_cv_fold_results.csv  -> Dummy
    # linear_svc_cv_fold_results.csv -> LinearSVC
    # etc.
    filename_model = os.path.basename(file).replace("_cv_fold_results.csv", "")

    # Use the model column if present, otherwise fallback to filename
    if "model" not in df.columns:
        df["model"] = filename_model

    # Create a cleaner label based on filename
    model_map = {
        "bernnb": "BernoulliNB",
        "dummy": "Dummy",
        "linear_svc": "LinearSVC",
        "mlp": "MLP",
        "sgd": "SGD",
        "xgb": "XGBoost"
    }
    df["model_label"] = model_map.get(filename_model, filename_model)

    dfs.append(df)

all_df = pd.concat(dfs, ignore_index=True)

# Keep only needed columns
all_df = all_df[["model_label", "fold", "accuracy", "macro_f1"]].copy()

print("Combined dataframe:")
print(all_df.head())
print("\nModels found:", all_df["model_label"].unique())


# --------------------------------------------------
# 2. Function to run ANOVA + Tukey HSD/Tukey-Kramer
# --------------------------------------------------

def run_anova_tukey(df, metric, alpha=0.05):
    """
    Runs one-way ANOVA and Tukey HSD on the given metric.
    Outputs:
      - ANOVA table
      - Tukey summary table
      - Custom pairwise table with abs mean diff, HSD, q-statistic, reject
    """
    print("\n" + "="*80)
    print(f"ANALYSIS FOR: {metric.upper()}")
    print("="*80)

    # --------------------------
    # Descriptive statistics
    # --------------------------
    summary = df.groupby("model_label")[metric].agg(["mean", "std", "count"])
    summary["se"] = summary["std"] / np.sqrt(summary["count"])
    print("\nDescriptive statistics:")
    print(summary)

    # --------------------------
    # One-way ANOVA
    # --------------------------
    model = ols(f"{metric} ~ C(model_label)", data=df).fit()
    anova_table = sm.stats.anova_lm(model, typ=2)

    print("\nOne-way ANOVA table:")
    print(anova_table)

    pval = anova_table["PR(>F)"].iloc[0]

    if pval >= alpha:
        print(f"\nANOVA not significant for {metric} (p = {pval:.6g}).")
        print("Skipping Tukey HSD.\n")
        return {
            "summary": summary,
            "anova": anova_table,
            "tukey_summary": None,
            "tukey_custom": None
        }

    print(f"\nANOVA significant for {metric} (p = {pval:.6g}). Running Tukey HSD...\n")

    # --------------------------
    # Tukey HSD / Tukey-Kramer
    # --------------------------
    tukey = pairwise_tukeyhsd(
        endog=df[metric],
        groups=df["model_label"],
        alpha=alpha
    )

    print("Tukey HSD summary:")
    print(tukey.summary())

    # Convert Tukey result to DataFrame
    tukey_df = pd.DataFrame(
        data=tukey._results_table.data[1:],
        columns=tukey._results_table.data[0]
    )

    # --------------------------
    # Build custom output table
    # --------------------------
    # Need:
    # - pair
    # - absolute difference of means
    # - HSD threshold
    # - q-statistic used
    # - reject or not
    #
    # For equal n, Tukey HSD threshold = q_crit * sqrt(MSE / n)
    # More generally, statsmodels handles Tukey-Kramer internally.
    # We'll compute pairwise q statistic using:
    # q = |mean_i - mean_j| / sqrt(MSE/2 * (1/n_i + 1/n_j))
    # HSD threshold (pair-specific Tukey-Kramer threshold):
    # HSD_pair = q_crit * sqrt(MSE/2 * (1/n_i + 1/n_j))
    #
    # reject if abs diff > HSD_pair

    means = df.groupby("model_label")[metric].mean()
    counts = df.groupby("model_label")[metric].count()

    mse = anova_table.loc["Residual", "sum_sq"] / anova_table.loc["Residual", "df"]
    k = df["model_label"].nunique()
    df_error = anova_table.loc["Residual", "df"]

    q_crit = qsturng(1 - alpha, k, df_error)

    custom_rows = []

    for _, row in tukey_df.iterrows():
        g1 = row["group1"]
        g2 = row["group2"]

        mean1 = means[g1]
        mean2 = means[g2]
        n1 = counts[g1]
        n2 = counts[g2]

        abs_diff = abs(mean1 - mean2)

        se_pair = np.sqrt((mse / 2) * (1/n1 + 1/n2))
        q_stat = abs_diff / se_pair
        hsd_pair = q_crit * se_pair

        custom_rows.append({
            "pair": f"{g1} vs {g2}",
            "mean_1": mean1,
            "mean_2": mean2,
            "abs_mean_diff": abs_diff,
            "q_value_used": q_crit,
            "q_statistic": q_stat,
            "HSD": hsd_pair,
            "reject": abs_diff > hsd_pair
        })

    custom_df = pd.DataFrame(custom_rows)

    print("\nCustom Tukey table:")
    print(custom_df)

    return {
        "summary": summary,
        "anova": anova_table,
        "tukey_summary": tukey_df,
        "tukey_custom": custom_df
    }


# --------------------------------------------------
# 3. Run for ACCURACY
# --------------------------------------------------

accuracy_results = run_anova_tukey(all_df, metric="accuracy", alpha=0.05)

# --------------------------------------------------
# 4. Run for MACRO F1
# --------------------------------------------------

f1_results = run_anova_tukey(all_df, metric="macro_f1", alpha=0.05)


# --------------------------------------------------
# 5. Optional: save outputs to CSV
# --------------------------------------------------

if accuracy_results["summary"] is not None:
    accuracy_results["summary"].to_csv("anova_accuracy_descriptive_stats.csv")
    accuracy_results["anova"].to_csv("anova_accuracy_table.csv")
    if accuracy_results["tukey_summary"] is not None:
        accuracy_results["tukey_summary"].to_csv("tukey_accuracy_summary.csv", index=False)
    if accuracy_results["tukey_custom"] is not None:
        accuracy_results["tukey_custom"].to_csv("tukey_accuracy_custom.csv", index=False)

if f1_results["summary"] is not None:
    f1_results["summary"].to_csv("anova_macro_f1_descriptive_stats.csv")
    f1_results["anova"].to_csv("anova_macro_f1_table.csv")
    if f1_results["tukey_summary"] is not None:
        f1_results["tukey_summary"].to_csv("tukey_macro_f1_summary.csv", index=False)
    if f1_results["tukey_custom"] is not None:
        f1_results["tukey_custom"].to_csv("tukey_macro_f1_custom.csv", index=False)

print("\nDone. CSV outputs saved.")